/*

assignment 1,
Mitchello Pierre Rene

this program keeps a record of students. User are responsible for inputing thngs like name, int and major. 
For is store in a vectorList. The user interacts with a menu based do while loop to choose different options.
Like adding students, printing students, and search operations like by name and id number.

*/

#include <iostream>
#include <string>
#include "studentMethods.cpp"


using namespace std;


int main()
{

    string menuInput;
    int idUpperLimit = 999999, idLowerLimit = 100000;
    int ageUpperLimit = 65, ageLowerLimit = 18;

    bool Quit = false;

    do
    {
        std::cout << endl
                  << "to add student enter 1: " << endl
                  << "to search by full name enter 2: " << endl
                  << "to search by id enter 3: " << endl
                  << "to print all students enter 4: " << endl
                  << "to quit enter Q: " << endl
                  << endl
                  << "input: ";



        try
        {
            std::cin >> menuInput;
            std::cin.ignore();
            cout << endl;

            if (menuInput == "Q")
            {
                Quit = true;
                cout << "exiting the program, thank you!";
                continue;
            };
            stoi(menuInput);
        }
        catch(const std::exception& e)
        {

        }


        switch (menuInput)
        {

        case 1:
        {
            Student user{};

            string User_nameInput;
            std::cout << "please enter Student full name ";

            std::getline(std::cin, User_nameInput);
            user.setName(User_nameInput);

            int User_ageInput;
            std::cout << "please enter student age(18+) ";
            std::cin >> User_ageInput;

            if(User_ageInput > ageUpperLimit || User_ageInput < ageLowerLimit){

                cout<<endl<<"invalid age!"<<endl;
                continue;
            }
            user.setAge(User_ageInput);

            int User_idInput;
            std::cout << "Please enter student ID ";
            std::cin >> User_idInput;

            if(User_idInput > idUpperLimit || User_idInput < idLowerLimit){

                cout<<endl<<"invalid ID!"<<endl;
                continue;
            }

            user.setID(User_idInput);

            // dont ask for major, give a choice
            string User_majorInput;
            std::cout << "Please enter student's major ";
            std::cin >> User_majorInput;
            user.setMajor(User_majorInput);

            // use student name with email extension
            string emailExtension = "@uni.edu";
            user.setEmail(user.getName() + emailExtension);

            studentList.push_back(user);

            break;
        }

        case 2:
        {
            string nameSearch;
            cout << "please enter the name to search: ";
            cin >> nameSearch;
            cin.ignore();
            cout << endl;

            Student searchResult = searchByFullName(studentList, nameSearch);

            headerTemplate();
            Student::printStudent(searchResult);
            std::cout << endl;

            break;
        }
        case 3:
        {

            int idSearch;
            cout << "please enter the ID to search: ";
            cin >> idSearch;
            cout << endl;

            Student searchResult = searchByID(studentList, idSearch);

            headerTemplate();
            Student::printStudent(searchResult);
            std::cout << endl;

            break;
        }
        case 4:
        {
            headerTemplate();
            displayAllStudents(studentList);
            break;
        }

        default:

            cout << "a valid menu choice was not entered"<<endl;

            break;
        }

    } while (!Quit);

    return 0;
}

#include <iostream>
#include <string>
#include "Student.cpp"
#include <vector>

using namespace std;

vector<Student> studentList{};

void displayAllStudents(vector<Student> &studentList)
{
    if (studentList.size() == 0)
    {
        cout << "There are currently no students to print" << endl;
    }
    else
    {

        for (int i = 0; i < studentList.size(); i++)
            Student::printStudent(studentList[i]);
    }
}
Student searchByFullName(vector<Student> &studentList, string fullName)
{

    Student noStudentFlag{-1, "N/A", -1, "N/A", "N/A"};
    for (int i = 0; i < studentList.size(); i++)
    {


        if (studentList[i].getName() == fullName)
        {
            return studentList[i];
        }
    }
    std::cout << endl
              << "Student not found in the registery \n"
              << endl;

    return noStudentFlag;
}
Student searchByID(vector<Student> &studentList, int IDSearch)
{

    Student noStudentFlag{-1, "N/A", -1, "N/A", "N/A"};
    for (int i = 0; i < studentList.size(); i++)
    {

        if (studentList[i].getID() == IDSearch)
        {
            return studentList[i];
        }
    }

    std::cout << endl
              << "Student not found in the registery \n"
              << endl;

    return noStudentFlag;
}
void headerTemplate()
{
    std::cout << "ID " << std::setw(10) << "Name" << std::setw(20) << "Age" << std::setw(10) << "Major" << std::setw(20) << "Email" << std::endl;
    std::cout << " ---------------------------------------------------------------------" << std::endl;
}
